  function renderSummary(){if(state.networkMode==='standalone')return renderStandaloneSummary();const r=current(),values=r.companyRanges.map((x)=>x.base),dispersion=Math.max(...values)-Math.min(...values),interaction=r.base.secondOrder[0];el('industryRange').textContent=r.industryRange.low.toFixed(1)+' – '+r.industryRange.high.toFixed(1);el('industryBase').textContent='基准 '+r.industryRange.base.toFixed(1);el('bottleneck').textContent=r.base.constraints[0]?.label||'无显著瓶颈';el('interaction').textContent=interaction?.label||'无显著交叉项';el('dispersion').textContent=dispersion.toFixed(1)+' pp'}
