  function renderCompany(){if(state.networkMode==='standalone')return renderStandaloneCompany();setCompanyModelSections(false);const r=current(),company=r.base.companies.find((x)=>x.id===state.selectedCompany)||r.base.companies[0],market=window.NEXUS_V214_MARKET_VALUATION.evaluate(company);el('companyTitle').textContent=company.name+' · CANDIDATE VALUATION';el('companySelect').value=company.id;el('modelFamily').textContent=company.modelFamily;el('modelFormula').textContent=company.modelLabel;el('companyDriverGrid').innerHTML=company.drivers.map((driver)=>'<div><span>'+esc(driver.label)+' · 模型变化</span><strong class="'+(driver.value<0?'negative':'')+'">'+fmt(driver.value)+'</strong><small>'+esc(driver.id.toUpperCase())+' · NOT REPORTED ACTUAL</small></div>').join('');const steps=[['当前市值',market.currentMarketCap,'候选行情'],['收入模型变化',company.revenue,company.modelLabel],['利润率影响',company.margin,'经营模型'],['FCF 模型变化',company.fcf,'净债务桥接'],['估值倍数变化',company.multipleChange,'市场校准'],['情景市值变化',market.valueChangePct,'金额 '+market.valueChangeAmount+' '+market.currency+' bn']];el('driverTree').innerHTML=steps.map((s,index)=>'<div class="driver-step"><span>'+esc(s[0])+'</span><strong>'+(index===0?market.currency+' '+Number(s[1]).toFixed(1)+'bn':fmt(s[1]))+'</strong><small>'+esc(s[2])+'</small></div>').join('');const parts=[['经营变化',market.attribution.operations],['估值倍数',market.attribution.multiple],['FCF / 净债务',market.attribution.cashFlow],['市值变化合计',market.valueChangeAmount]],max=Math.max(1,...parts.map((x)=>Math.abs(x[1])));el('waterfallBars').innerHTML=parts.map(([label,value])=>waterfall(label,value,max)).join('');renderCompanyFinancials(company)}
  function waterfall(label,value,max){const height=Math.max(2,Math.abs(value)/max*44),bottom=value>=0?50:50-height;return'<div class="waterfall-item"><div class="waterfall-axis"><div class="waterfall-fill '+(value<0?'negative':'')+'" style="height:'+height+'%;bottom:'+bottom+'%"></div><span class="waterfall-value" style="'+(value>=0?'bottom:'+(52+height)+'%':'top:'+(52+height)+'%')+'">'+fmt(value)+'</span></div><b>'+label+'</b></div>'}
  function runtimeEntities(){return state.networkMode==='standalone'?runtimeCompanyEntities:data.nodes.filter((node)=>node.layer==='company')}
  function runtimeMetricName(code){return data.nodes.find((node)=>node.importSnapshot?.metricCodes?.includes(code))?.label||code}
  const financialMetricLabels={REVENUE:'营业收入',OPERATING_COST:'营业成本',NET_PROFIT:'归母净利润',OPERATING_CASH_FLOW:'经营活动现金流',TOTAL_ASSETS:'资产总额',TOTAL_LIABILITIES:'负债合计',POWER_GENERATION:'发电量',GRID_SALES_POWER:'上网电量',ON_GRID_TARIFF:'上网电价',INSTALLED_CAPACITY:'装机容量',CLOSE_PRICE:'收盘价',COAL_PRICE_5500:'5500大卡煤价',COAL_PRICE_5000:'5000大卡煤价'};
  const financialLabel=(code)=>financialMetricLabels[code]||runtimeMetricName(code)||code;
  const financialStatusLabels={SOURCE_FACT:'来源事实',MARKET_PROXY:'市场代理',DATABASE_CANDIDATE:'数据库候选',CALCULATED_LINEAGE_CANDIDATE:'计算候选',IMPORTED_SNAPSHOT_CANDIDATE:'导入快照候选',REPORTED_ACTUAL:'已披露值',DATA_MISSING:'数据缺失'};
  const financialUpdateDate=(item)=>item.announcementDate||item.asOfDate||item.as_of_date||item.opdate||null;
  const financialStatus=(item)=>{const raw=item.valueStatus||'IMPORTED_SNAPSHOT_CANDIDATE',hasDate=Boolean(item.reportPeriod||financialUpdateDate(item));if(!hasDate&&['SOURCE_FACT','REPORTED_ACTUAL'].includes(raw))return'导入候选（日期缺失） · IMPORTED_SNAPSHOT_CANDIDATE';return(financialStatusLabels[raw]||'候选数据')+' · '+raw};
  const financialSource=(item)=>[item.sourceTable,item.sourceColumn].filter(Boolean).join('.')||'来源未随网络包导入';
  const financialDateLabel=(item)=>{const period=item.reportPeriod,updated=financialUpdateDate(item),cutoff=item.dataCutoff;const dated=[period?'报告期 '+period:null,updated?'更新 '+updated:null].filter(Boolean);return dated.join(' · ')||(cutoff?'日期缺失 · 数据截止 '+cutoff:'日期缺失')};
  function companyFinancialRows(entity){
    if(!entity)return[];
    if(state.networkMode==='standalone'){
      const code=entity.importSnapshot?.entityCode;
      const sourceRows=(state.runtimeNetwork?.metricValues||[]).filter((item)=>!code||String(item.entityCode)===String(code));
      if(sourceRows.length)return sourceRows;
      return Object.entries(entity.importSnapshot?.baseline||{}).map(([metricCode,value])=>{const meta=entity.importSnapshot?.metricMetadata?.[metricCode]||{};return{metricCode,metricName:financialLabel(metricCode),value,unit:meta.unit||'',reportPeriod:meta.reportPeriod||null,announcementDate:meta.announcementDate||null,asOfDate:meta.asOfDate||null,opdate:meta.opdate||null,dataCutoff:meta.dataCutoff||state.runtimeNetwork?.dataCutoff||null,valueStatus:'IMPORTED_SNAPSHOT_CANDIDATE',declaredValueStatus:meta.declaredValueStatus||null,evidenceId:meta.evidenceId||null,sourceTable:meta.sourceTable||'网络快照',sourceColumn:meta.sourceColumn||metricCode,sourceRowKey:meta.sourceRowKey||null}});
    }
    const company=data.companies.find((item)=>item.id===entity.id),financial=window.NEXUS_COAL_DB_SNAPSHOT?.companies?.[entity.ticker]||Object.values(window.NEXUS_COAL_DB_SNAPSHOT?.companies||{}).find((item)=>item.code===company?.ticker);
    if(!financial)return[];
    const fields=[['REVENUE',financial.revenueBn,'十亿元'],['NET_PROFIT',financial.netProfitBn,'十亿元'],['OPERATING_CASH_FLOW',financial.cfoBn,'十亿元'],['TOTAL_ASSETS',financial.assetsBn,'十亿元'],['TOTAL_LIABILITIES',financial.liabilitiesBn,'十亿元']];
    return fields.filter(([,value])=>value!=null).map(([metricCode,value,unit])=>({metricCode,metricName:financialLabel(metricCode),value,unit,reportPeriod:financial.reportPeriod,announcementDate:financial.availableAt,dataCutoff:window.NEXUS_COAL_DB_SNAPSHOT?.coverage?.financialCutoff,valueStatus:financial.financialStatus||'DATABASE_CANDIDATE',sourceTable:financial.financialSource||'PostgreSQL'}));
  }
  function renderCompanyFinancials(entity){
    const latestEl=el('companyLatestFinancials'),historyEl=el('companyFinancialHistory'),statusEl=el('companyFinancialStatus');if(!latestEl||!historyEl||!statusEl)return;
    const rows=companyFinancialRows(entity),dateKey=(item)=>[item.reportPeriod,item.announcementDate,item.asOfDate,item.as_of_date,item.opdate,item.dataCutoff,item.version].map((value)=>String(value||'')).join('|');
    const sorted=rows.slice().sort((a,b)=>dateKey(b).localeCompare(dateKey(a))||String(a.metricCode).localeCompare(String(b.metricCode))),latest=[],seen=new Set();sorted.forEach((item)=>{if(!seen.has(item.metricCode)){seen.add(item.metricCode);latest.push(item)}});
    const missingDateCount=rows.filter((item)=>!item.reportPeriod&&!financialUpdateDate(item)).length;statusEl.textContent=rows.length?(state.networkMode==='standalone'?(missingDateCount?'导入候选 · '+missingDateCount+'/'+rows.length+' 条日期缺失':'导入候选 · '+rows.length+' 条日期完整'):'数据库候选 · '+rows.length+' 条'):'DATA_MISSING';
    statusEl.classList.toggle('missing',missingDateCount>0);
    latestEl.innerHTML=latest.slice(0,12).map((item)=>'<div><span>'+esc(item.metricName||financialLabel(item.metricCode))+'</span><strong>'+esc(displayValue(item.value))+(item.unit?' '+esc(item.unit):'')+'</strong><small>'+esc(financialDateLabel(item))+'<br>'+esc(financialStatus(item))+'</small></div>').join('')||'<div class="company-history-empty">当前公司没有可展示的数据。状态：DATA_MISSING</div>';
    historyEl.innerHTML=sorted.slice(0,160).map((item)=>'<tr><td>'+esc(item.metricName||financialLabel(item.metricCode))+'</td><td>'+esc(displayValue(item.value))+(item.unit?' '+esc(item.unit):'')+'</td><td>'+esc(item.reportPeriod||'报告期缺失')+'</td><td>'+esc(financialUpdateDate(item)||'日期缺失')+'</td><td>'+esc(financialSource(item))+'</td><td class="status">'+esc(financialStatus(item))+'</td></tr>').join('')||'<tr><td colspan="6" class="company-history-empty">暂无历史记录。只有携带报告期、日期和来源的数据才会标记为来源事实。</td></tr>';
  }  function displayValue(value){return typeof value==='number'?value.toLocaleString('zh-CN',{maximumFractionDigits:2}):String(value??'DATA_MISSING')}
